// D8 drives the ULN2003's IN1; OUT1 sinks the relay coil's current from 5 V.
void setup() {
  pinMode(8, OUTPUT);
}

void loop() {
  digitalWrite(8, HIGH);  // channel 1 on: the relay pulls in
  delay(1000);
  digitalWrite(8, LOW);   // channel 1 off: the clamp diode to COM takes the coil's current
  delay(1000);
}
